import{_ as d,o as e,c as a,a2 as o}from"./chunks/framework.Bg-Zxr5O.js";const E=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/SELECT-IF.md","filePath":"manual-zh/SELECT-IF.md","lastUpdated":1785684581000}'),s={name:"manual-zh/SELECT-IF.md"};function r(c,t,n,p,l,i){return e(),a("div",null,[...t[0]||(t[0]=[o(`<h3 id="_13-4-select-if" tabindex="-1">13.4 SELECT IF <a class="header-anchor" href="#_13-4-select-if" aria-label="Permalink to &quot;13.4 SELECT IF&quot;">​</a></h3><pre><code>SELECT IF expression.
</code></pre><p><code>SELECT IF</code> 根据表达式的取值来选择用于分析的个案。未被选中的个案将从活动数据集中永久剔除，除非 <code>TEMPORARY</code> 生效（参见 <a href="./TEMPORARY">TEMPORARY</a>）。</p><p>指定一个布尔表达式（参见 <a href="./Expressions">Expressions</a>）。如果某个个案的表达式值为真，则该个案被分析。如果表达式的值为假或缺失，则该个案从数据流中删除。</p><p>应将 <code>SELECT IF</code> 尽量放在命令文件靠前的位置。尽早删除的个案可以在时间和空间上得到更高效的处理。一旦使用 <code>SELECT IF</code> 从活动数据集中删除了个案，就无法再恢复。如果想要能够恢复个案，则应改用 <code>FILTER</code>（参见 <a href="./FILTER">FILTER</a>）。</p><p>当 <code>SELECT IF</code> 出现在 <code>TEMPORARY</code> 之后时（参见 <a href="./TEMPORARY">TEMPORARY</a>），不能使用 <code>LAG</code> 函数（参见 <a href="./Miscellaneous-Functions#LAG">LAG</a>）。</p><h4 id="_13-4-1-示例-select-if" tabindex="-1">13.4.1 示例 Select-If <a class="header-anchor" href="#_13-4-1-示例-select-if" aria-label="Permalink to &quot;13.4.1 示例 Select-If&quot;">​</a></h4><p>一位工会代表对一家公司中年轻员工的薪资感兴趣。personnel.sav 文件提供了所有员工的薪资及其出生日期。示例 13.1 中的语法展示了如何使用 <code>SELECT IF</code> 将分析限制为仅出生于 1999 年 12 月 31 日之后的人。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>get file = &#39;personnel.sav&#39;.  echo &#39;Salaries of all personnel&#39;. descriptives salary.  echo &#39;Salaries of personnel born after December 31 1999&#39;. select if dob &gt; date.dmy (31,12,1999). descriptives salary.</span></span></code></pre></div><p><strong>示例 13.1：</strong> 使用 <code>SELECT IF</code> 选择出生于某一日期当天或之后的人。</p><p>从结果 13.1 可以看出，数据集中列出了 56 人，其中 17 人出生于 1999 年 12 月 31 日之后。</p><table tabindex="0"><thead><tr><th></th><th>N</th><th>均值</th><th>标准差</th><th>最小值</th><th>最大值</th></tr></thead><tbody><tr><td>税前年薪</td><td>56</td><td>40028.97</td><td>8721.17</td><td>$23,451</td><td>$57,044</td></tr><tr><td>有效 N（列表方式）</td><td>56</td><td></td><td></td><td></td><td></td></tr><tr><td>缺失 N（列表方式）</td><td>0</td><td></td><td></td><td></td><td></td></tr><tr><td></td><td>N</td><td>均值</td><td>标准差</td><td>最小值</td><td>最大值</td></tr><tr><td>税前年薪</td><td>17</td><td>31828.59</td><td>4454.80</td><td>$23,451</td><td>$39,504</td></tr><tr><td>有效 N（列表方式）</td><td>17</td><td></td><td></td><td></td><td></td></tr><tr><td>缺失 N（列表方式）</td><td>0</td><td></td><td></td><td></td><td></td></tr></tbody></table><p><strong>结果 13.1：</strong> <code>SELECT IF</code> 转换之前和之后的薪资描述统计。</p><p>注意，读取数据的 personnel.sav 文件不受影响。该转换只影响活动文件。</p>`,14)])])}const T=d(s,[["render",r]]);export{E as __pageData,T as default};
